-- Workspace schema version 2: the docs/CONTRACT.md §4.3 assets, rights, derived totals, audit, import and search objects.
-- Contacts, pitches, messages and reports, with their guards and indexes, are version 3.
-- ---------- Assets ----------
-- storage_key is generated by AssetService as <workspaceId>/<assetId>/<sanitized file name> (AST-001).
CREATE TABLE assets (
  id                TEXT PRIMARY KEY,                         -- ast_<ulid>
  asset_type        TEXT NOT NULL
                    CHECK (asset_type IN ('audio','image','document','agreement_pdf','report_pdf','import_source','other')),
  storage_provider  TEXT NOT NULL CHECK (storage_provider IN ('local','r2')),
  storage_key       TEXT NOT NULL CHECK (length(storage_key) > 0 AND substr(storage_key, 1, 1) != '/'),
  file_name         TEXT NOT NULL,
  mime_type         TEXT,
  byte_size         INTEGER CHECK (byte_size IS NULL OR byte_size >= 0),
  checksum_sha256   TEXT,
  created_at        TEXT NOT NULL,
  created_by        TEXT,
  UNIQUE (storage_provider, storage_key)
);
--> statement-breakpoint
CREATE TABLE composition_assets (
  composition_id  TEXT NOT NULL REFERENCES compositions(id) ON DELETE CASCADE,
  asset_id        TEXT NOT NULL REFERENCES assets(id) ON DELETE RESTRICT,
  relationship    TEXT NOT NULL CHECK (relationship IN ('lyrics_sheet','lead_sheet','other')),
  PRIMARY KEY (composition_id, asset_id, relationship)
);
--> statement-breakpoint
CREATE TABLE recording_assets (
  recording_id  TEXT NOT NULL REFERENCES recordings(id) ON DELETE CASCADE,
  asset_id      TEXT NOT NULL REFERENCES assets(id) ON DELETE RESTRICT,
  relationship  TEXT NOT NULL
                CHECK (relationship IN ('audio_master','audio_preview','instrumental','stems','artwork','other')),
  PRIMARY KEY (recording_id, asset_id, relationship)
);
--> statement-breakpoint
CREATE TABLE release_assets (
  release_id    TEXT NOT NULL REFERENCES releases(id) ON DELETE CASCADE,
  asset_id      TEXT NOT NULL REFERENCES assets(id) ON DELETE RESTRICT,
  relationship  TEXT NOT NULL CHECK (relationship IN ('cover_art','back_cover','booklet','other')),
  PRIMARY KEY (release_id, asset_id, relationship)
);
--> statement-breakpoint
CREATE TABLE asset_credits (
  asset_id  TEXT NOT NULL REFERENCES assets(id) ON DELETE CASCADE,
  party_id  TEXT NOT NULL REFERENCES parties(id) ON DELETE RESTRICT,
  role      TEXT NOT NULL DEFAULT 'artwork',
  PRIMARY KEY (asset_id, party_id, role)
);
--> statement-breakpoint
-- ---------- Rights ----------
CREATE TABLE agreements (
  id                     TEXT PRIMARY KEY,                    -- agr_<ulid>
  agreement_type         TEXT NOT NULL
                         CHECK (agreement_type IN ('publishing','master','representation','licensing','other')),
  title                  TEXT NOT NULL,
  counterparty_party_id  TEXT REFERENCES parties(id) ON DELETE RESTRICT,
  effective_on           TEXT,
  expires_on             TEXT,
  asset_id               TEXT REFERENCES assets(id) ON DELETE RESTRICT,
  notes                  TEXT,
  created_at             TEXT NOT NULL,
  updated_at             TEXT NOT NULL,
  created_by             TEXT,
  updated_by             TEXT
);
--> statement-breakpoint
-- One row per writer party per composition, so a share counts once however many roles the writer holds.
-- Writers are natural persons: the composite key rejects organization parties.
CREATE TABLE composition_contributors (
  id               TEXT PRIMARY KEY,                          -- ctr_<ulid>
  composition_id   TEXT NOT NULL REFERENCES compositions(id) ON DELETE RESTRICT,
  party_id         TEXT NOT NULL,
  party_kind       TEXT NOT NULL DEFAULT 'person' CHECK (party_kind = 'person'),
  writer_share_bp  INTEGER CHECK (writer_share_bp IS NULL OR writer_share_bp BETWEEN 0 AND 10000),
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  created_by       TEXT,
  updated_by       TEXT,
  UNIQUE (composition_id, party_id),
  FOREIGN KEY (party_id, party_kind) REFERENCES parties(id, party_kind) ON DELETE RESTRICT
);
--> statement-breakpoint
CREATE TABLE composition_contributor_roles (
  contributor_id  TEXT NOT NULL REFERENCES composition_contributors(id) ON DELETE CASCADE,
  role            TEXT NOT NULL CHECK (role IN ('songwriter','composer','lyricist','arranger')),
  PRIMARY KEY (contributor_id, role)
);
--> statement-breakpoint
-- territory: 'WORLD' or an ISO 3166-1 alpha-2 code. Totals are validated per territory (RGT-007, P-05).
-- representation_attested_*: the workspace's self publishing party is authorized to represent this
-- holder's share for licensing (§6.5). Rows held by the self party count as covered without attestation.
CREATE TABLE publishing_interests (
  id                          TEXT PRIMARY KEY,
  composition_id              TEXT NOT NULL REFERENCES compositions(id) ON DELETE RESTRICT,
  publisher_party_id          TEXT NOT NULL REFERENCES parties(id) ON DELETE RESTRICT,
  share_bp                    INTEGER NOT NULL CHECK (share_bp BETWEEN 0 AND 10000),
  territory                   TEXT NOT NULL DEFAULT 'WORLD'
                              CHECK (territory = 'WORLD' OR (length(territory) = 2 AND territory NOT GLOB '*[^A-Z]*')),
  agreement_id                TEXT REFERENCES agreements(id) ON DELETE RESTRICT,
  representation_attested_at  TEXT,
  representation_attested_by  TEXT,
  created_at                  TEXT NOT NULL,
  updated_at                  TEXT NOT NULL,
  created_by                  TEXT,
  updated_by                  TEXT,
  UNIQUE (composition_id, publisher_party_id, territory),
  CHECK ((representation_attested_at IS NULL) = (representation_attested_by IS NULL))
);
--> statement-breakpoint
CREATE TABLE master_interests (
  id                          TEXT PRIMARY KEY,
  recording_id                TEXT NOT NULL REFERENCES recordings(id) ON DELETE RESTRICT,
  owner_party_id              TEXT NOT NULL REFERENCES parties(id) ON DELETE RESTRICT,
  share_bp                    INTEGER NOT NULL CHECK (share_bp BETWEEN 0 AND 10000),
  agreement_id                TEXT REFERENCES agreements(id) ON DELETE RESTRICT,
  representation_attested_at  TEXT,
  representation_attested_by  TEXT,
  created_at                  TEXT NOT NULL,
  updated_at                  TEXT NOT NULL,
  created_by                  TEXT,
  updated_by                  TEXT,
  UNIQUE (recording_id, owner_party_id),
  CHECK ((representation_attested_at IS NULL) = (representation_attested_by IS NULL))
);
--> statement-breakpoint
-- The person or company a licensee contacts for this song (§6.5). Exactly one target.
CREATE TABLE licensing_contacts (
  id              TEXT PRIMARY KEY,                           -- lic_<ulid>
  recording_id    TEXT REFERENCES recordings(id) ON DELETE RESTRICT,
  composition_id  TEXT REFERENCES compositions(id) ON DELETE RESTRICT,
  party_id        TEXT NOT NULL REFERENCES parties(id) ON DELETE RESTRICT,
  agreement_id    TEXT REFERENCES agreements(id) ON DELETE RESTRICT,
  notes           TEXT,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL,
  created_by      TEXT,
  updated_by      TEXT,
  CHECK ((recording_id IS NULL) != (composition_id IS NULL))
);
--> statement-breakpoint
-- ---------- Derived totals (never stored; live rows only) ----------
CREATE VIEW composition_writer_totals AS
  SELECT c.id AS composition_id,
         COALESCE(SUM(cc.writer_share_bp), 0) AS writer_total_bp,
         COUNT(cc.id) AS writer_count
  FROM compositions c
  LEFT JOIN composition_contributors cc ON cc.composition_id = c.id
  WHERE c.deleted_at IS NULL
  GROUP BY c.id;
--> statement-breakpoint
CREATE VIEW composition_publishing_totals AS
  SELECT pi.composition_id, pi.territory,
         SUM(pi.share_bp) AS publishing_total_bp,
         COUNT(*) AS publisher_count
  FROM publishing_interests pi
  JOIN compositions c ON c.id = pi.composition_id
  WHERE c.deleted_at IS NULL
  GROUP BY pi.composition_id, pi.territory;
--> statement-breakpoint
CREATE VIEW recording_master_totals AS
  SELECT r.id AS recording_id,
         COALESCE(SUM(mi.share_bp), 0) AS master_total_bp,
         COUNT(mi.id) AS owner_count
  FROM recordings r
  LEFT JOIN master_interests mi ON mi.recording_id = r.id
  WHERE r.deleted_at IS NULL
  GROUP BY r.id;
--> statement-breakpoint
-- ---------- Audit (no foreign keys: rows outlive the entities they describe) ----------
CREATE TABLE audit_log (
  id                     TEXT PRIMARY KEY,                    -- aud_<ulid>
  actor_type             TEXT NOT NULL CHECK (actor_type IN ('user','agent','system','import')),
  actor_user_id          TEXT,
  agent_run_id           TEXT,
  approval_tool_call_id  TEXT,
  action                 TEXT NOT NULL,   -- §6.6 vocabulary
  entity_type            TEXT NOT NULL,
  entity_id              TEXT NOT NULL,
  before_json            TEXT,
  after_json             TEXT,
  request_id             TEXT,
  occurred_at            TEXT NOT NULL
);
--> statement-breakpoint
-- ---------- Import (Airtable and CSV share one pipeline, §7.6) ----------
CREATE TABLE import_runs (
  id                      TEXT PRIMARY KEY,                   -- imp_<ulid>
  source_system           TEXT NOT NULL CHECK (source_system IN ('airtable','csv')),
  source_container        TEXT NOT NULL,   -- Airtable base id, or the CSV source key chosen by the user
  mode                    TEXT NOT NULL CHECK (mode IN ('dry_run','apply')),
  dry_run_id              TEXT REFERENCES import_runs(id),
  source_snapshot_sha256  TEXT NOT NULL,
  source_asset_id         TEXT REFERENCES assets(id) ON DELETE RESTRICT,  -- uploaded CSV file
  full_snapshot           INTEGER NOT NULL CHECK (full_snapshot IN (0,1)),  -- 0: CSV subset, no row-level orphans (P-40)
  status                  TEXT NOT NULL
                          CHECK (status IN ('running','succeeded','failed','blocked','partial')),
  planned_json            TEXT,   -- per target table: create, update, unchanged, orphaned, conflict
  result_json             TEXT,
  resume_cursor           TEXT,   -- last committed batch for resumable apply (IMP-013)
  started_by              TEXT NOT NULL,
  started_at              TEXT NOT NULL,
  finished_at             TEXT,
  CHECK (mode = 'dry_run' OR dry_run_id IS NOT NULL),
  CHECK (source_system = 'csv' OR full_snapshot = 1)
);
--> statement-breakpoint
CREATE TABLE import_issues (
  id                TEXT PRIMARY KEY,                         -- iss_<ulid>
  import_run_id     TEXT NOT NULL REFERENCES import_runs(id) ON DELETE CASCADE,
  severity          TEXT NOT NULL CHECK (severity IN ('info','warning','error')),
  code              TEXT NOT NULL,
  source_table      TEXT,
  source_record_id  TEXT,
  field             TEXT,
  message           TEXT NOT NULL
);
--> statement-breakpoint
-- One row per (source record, target role, target key). target_key separates several targets of one
-- role produced by one source row, such as two writers from one CSV row (§7.6). Share rows are
-- referenced by natural key in entity_id, so full-set share replacement never orphans a reference.
-- applied_row_sha256 is the hash of the mapped target values re-read right after the importer's last write; a
-- different current hash means the row was edited in Melos (IMP-004).
CREATE TABLE external_references (
  id                     TEXT PRIMARY KEY,                    -- xref_<ulid>
  source_system          TEXT NOT NULL CHECK (source_system IN ('airtable','csv')),
  source_container       TEXT NOT NULL,
  source_table           TEXT NOT NULL,   -- Airtable table name; 'rows' for CSV
  source_record_id       TEXT NOT NULL,   -- Airtable record id; CSV external_id or ISRC
  target_role            TEXT NOT NULL,   -- composition, recording, release, writer_share, publishing_share, ...
  target_key             TEXT NOT NULL DEFAULT '',
  entity_type            TEXT NOT NULL,
  entity_id              TEXT NOT NULL,
  source_payload_sha256  TEXT NOT NULL,
  applied_row_sha256     TEXT NOT NULL,
  metadata_json          TEXT,
  first_import_run_id    TEXT NOT NULL REFERENCES import_runs(id),
  last_import_run_id     TEXT NOT NULL REFERENCES import_runs(id),
  last_applied_at        TEXT NOT NULL,
  UNIQUE (source_system, source_container, source_table, source_record_id, target_role, target_key)
);
--> statement-breakpoint
-- ---------- Search (FTS5 is preloaded on Turso: SRC-019; local libSQL files U-08) ----------
-- Maintained by CatalogService in the same transaction as catalog writes. Query building: §3.5.
CREATE VIRTUAL TABLE catalog_search USING fts5(
  entity_type UNINDEXED,
  entity_id UNINDEXED,
  title,
  alt_titles,
  artist_names,
  contributor_names,
  terms,
  lyrics
);
--> statement-breakpoint
-- ---------- Guards on these tables (§4.3) ----------
CREATE TRIGGER audit_log_no_update BEFORE UPDATE ON audit_log
BEGIN SELECT RAISE(ABORT, 'audit_log is append-only'); END;
--> statement-breakpoint
CREATE TRIGGER audit_log_no_delete BEFORE DELETE ON audit_log
BEGIN SELECT RAISE(ABORT, 'audit_log is append-only'); END;
--> statement-breakpoint
-- ---------- Indexes on these tables (§4.3) ----------
CREATE INDEX idx_contrib_composition      ON composition_contributors(composition_id);--> statement-breakpoint
CREATE INDEX idx_contrib_party            ON composition_contributors(party_id);--> statement-breakpoint
CREATE INDEX idx_publish_composition      ON publishing_interests(composition_id, territory);--> statement-breakpoint
CREATE INDEX idx_publish_party            ON publishing_interests(publisher_party_id);--> statement-breakpoint
CREATE INDEX idx_master_recording         ON master_interests(recording_id);--> statement-breakpoint
CREATE INDEX idx_master_party             ON master_interests(owner_party_id);--> statement-breakpoint
CREATE INDEX idx_licensing_recording      ON licensing_contacts(recording_id);--> statement-breakpoint
CREATE INDEX idx_licensing_composition    ON licensing_contacts(composition_id);--> statement-breakpoint
CREATE INDEX idx_audit_entity_time        ON audit_log(entity_type, entity_id, occurred_at DESC);--> statement-breakpoint
CREATE INDEX idx_audit_time               ON audit_log(occurred_at DESC);--> statement-breakpoint
CREATE INDEX idx_external_refs_entity     ON external_references(entity_type, entity_id);--> statement-breakpoint
CREATE INDEX idx_import_issues_run        ON import_issues(import_run_id, severity);
